fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(2, 0);
        host::display::state_set(3, 240);
        host::display::state_set(4, 0);
        host::display::state_set(6, 0);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(5);
    host::display::state_set(5, down);
    let mut alt: i32 = host::display::state_get(1);
    let mut v: i32 = host::display::state_get(2);
    let mut fuel: i32 = host::display::state_get(3);
    let phase: i32 = host::display::state_get(4);
    let mut flew: i32 = host::display::state_get(6);
    let thrusting: bool = phase == 0 && down == 1 && fuel > 0;
    if phase == 0 {
        if thrusting {
            v = v + 9;
            fuel = fuel - 1;
        }
        v = v - 4;
        alt = alt + v;
        if alt > 640 { flew = 1; }
        if alt <= 0 {
            alt = 0;
            if flew == 1 {
                if v < -40 {
                    host::display::state_set(4, 1);
                } else {
                    host::display::state_set(4, 2);
                }
            }
            v = 0;
        }
        host::display::state_set(1, alt);
        host::display::state_set(2, v);
        host::display::state_set(3, fuel);
        host::display::state_set(6, flew);
    } else {
        if down == 1 && prev == 0 {
            host::display::state_set(0, 0);
        }
    }
    host::display::clear(0x080810);
    host::display::fill_rect(0, h - 24, w, 24, 0x303428);
    host::display::fill_rect(w / 2 - 30, h - 30, 60, 6, 0x505050);
    let mut ry: i32 = h - 30 - 36 - alt / 8;
    if ry < 40 { ry = 40; }
    host::display::fill_rect(w / 2 - 8, ry, 16, 36, 0xd0d0d8);
    host::display::fill_rect(w / 2 - 8, ry - 10, 16, 10, 0xa04040);
    if thrusting {
        host::display::fill_rect(w / 2 - 5, ry + 36, 10, 14, 0xffa020);
    }
    host::display::draw_string(8, 8, "FUEL", 0x808080, 1);
    host::display::fill_rect(50, 8, fuel, 8, 0x40a0ff);
    host::display::draw_string(8, 24, "ALT", 0x808080, 1);
    host::display::draw_number(50, 24, alt / 8, 0xffffff, 1);
    host::display::draw_string(8, 40, "SPD", 0x808080, 1);
    host::display::draw_number(50, 40, iabs(v) / 8, 0xffffff, 1);
    if v > 0 { host::display::draw_char(90, 40, 94, 0x40ff60, 1); }
    if v < 0 { host::display::draw_char(90, 40, 118, 0xff5050, 1); }
    if phase == 1 {
        host::display::draw_string(w / 2 - 60, 80, "CRASHED", 0xff4030, 3);
        host::display::draw_string(w / 2 - 70, 120, "TAP TO RETRY", 0x808080, 1);
    }
    if phase == 2 {
        host::display::draw_string(w / 2 - 55, 80, "LANDED", 0x40ff60, 3);
        host::display::draw_string(w / 2 - 70, 120, "TAP TO RETRY", 0x808080, 1);
    }
    if phase == 0 {
        host::display::draw_string(8, h - 44, "HOLD = THRUST", 0x606060, 1);
    }
    host::display::present();
}
